from functools import lru_cache
from itertools import combinations_with_replacement

def brute(a):
 n=len(a)
 @lru_cache(None)
 def f(mask):
  # max pairs among subset indices
  i=0
  while i<n and (mask>>i)&1: i+=1
  if i==n: return 0
  best=f(mask|1<<i) # leave i unused
  for j in range(i+1,n):
   if not ((mask>>j)&1) and 2*a[i]<=a[j]:
    best=max(best,1+f(mask|(1<<i)|(1<<j)))
  return best
